RegisterGlobalEvent(40301, "Quest", function()
    if IsQBitSet(QBit(110501)) then
        evt.SetMessage(NPCText(40300, "Crodo is free. Good. The King was pleased for almost a minute, and then asked about the mirror."))
        return
    end
    if IsQBitSet(QBit(111120)) then
        evt.SetMessage(NPCText(40301, "You haven't found Crodo yet. Keep searching."))
        return
    end
    if IsQBitSet(QBit(111100)) then
        evt.SetMessage(NPCText(40302, "Years ago King Burlock met Crodo, a kindly old sorcerer who became the King's friend. Baron Darzog, who was the King's master sorcerer, became very jealous of this friendship. I tried to warn the King that Darzog's jealousy would lead to no good, but he wouldn't listen to me. Now Crodo and Darzog have both disappeared and I fear that Crodo has been abducted. Perhaps Darzog has imprisoned him in his tower. If King Burlock were not so obsessed with the search for the Sixth Mirror, I'm sure he would have you search for him there."))
        SetQBit(QBit(111120))
        SetAutonote(4010)
        return
    end
    evt.SetMessage(NPCText(40303, "See the King first. Everyone sees the King first. Then they come to me."))
end)

RegisterGlobalEvent(40351, "Quest", function()
    if IsQBitSet(QBit(110100)) then
        evt.SetMessage(NPCText(40350, "The pyramid on the knoll east of Vertigo. Show it the sigil. Where it takes you, the King prefers not to know, so I don't tell him."))
        return
    end
    evt.SetMessage(NPCText(40351, "The old pyramids are said to lead to the land below the land. The Prince went there, they say, before he came home. The King will not hear of it. So, quietly: the Pyramid Sigil. Try the pyramid on the knoll east of Vertigo."))
    AddValue(InventoryItem(12302), 12302)
    SetQBit(QBit(110100))
    evt.ForPlayer(Players.All)
    AddValue(Experience, 1000)
