    end
    if Xeen.itemCount(12334) >= 5 then
        evt.SetMessage(NPCText(41302, "This is fantastic! Your speedy delivery has kept us on track. The dungeon returns now. Just five more discs will bring back the last of the castle."))
        RemoveItem(12334)
        RemoveItem(12334)
        RemoveItem(12334)
        RemoveItem(12334)
        RemoveItem(12334)
