    if HasItem(12331) then
        evt.SetMessage(NPCText(41401, "My orb. Without it I could see Alamar, but not strike him. Hear what I have seen. Alamar is not a king. He is Sheltem, a guardian the Ancients made to keep a world safe, who decided he knew better. He means to steer Xeen away from its sun and sail it like a ship. He came here in a pod from the stars. So did his pursuer, and that pod fell into lava in the Forbidden Zone. I have cooled it. Go."))
