    Xeen.promote("seasons")
end)
RegisterCanShowTopic(45851, function()
    return (IsQBitSet(QBit(112201)) and Xeen.canPromote("seasons"))
end)

RegisterGlobalEvent(45852, "Promotion", function()
    evt.SetMessage(NPCText(45851, "Carlawna sent word that you helped her. Leaves fall so the tree can grow. Druids rise as Great Druids, Clerics as Priests."))
    Xeen.promote("seasons")
end)
RegisterCanShowTopic(45852, function()
    return (IsQBitSet(QBit(112201)) and Xeen.canPromote("seasons"))
end)

RegisterGlobalEvent(45951, "Promotion", function()
    evt.SetMessage(NPCText(45950, "Another thief in your company? How useful. Rise, Rogue. Don't touch anything on the way out."))
    Xeen.promote("tiara")
end)
RegisterCanShowTopic(45951, function()
    return (IsQBitSet(QBit(112061)) and Xeen.canPromote("tiara"))
end)

RegisterGlobalEvent(46003, "Quest", function()
    if (IsQBitSet(QBit(114522)) and Xeen.canPromote("dimitri")) then
        evt.SetMessage(NPCText(46000, "Another knight in your company. Kneel. ... Rise, Champion of the Darkside. That's the whole ceremony; we lost the trumpets."))
        Xeen.promote("dimitri")
        return
    end
    if IsQBitSet(QBit(114522)) then
        evt.SetMessage(NPCText(46001, "The cells are quiet. The guard can sleep in the guardroom again, instead of on the stairs."))
        return
    end
    if IsQBitSet(QBit(114521)) then
        evt.SetMessage(NPCText(46002, "Quiet down there. Truly quiet. Those of you who ride and fight as knights: kneel. ... Rise, Champions of the Darkside. The rest of you: the Queen's thanks, and mine."))
        SetQBit(QBit(114522))
        evt.ForPlayer(Players.All)
        AddValue(Experience, 6000)
        Xeen.promote("dimitri")
        return
    end
    if IsQBitSet(QBit(114520)) then
        evt.SetMessage(NPCText(46003, "The liches are still down there. You can hear them filing their nails. On the bars."))
        return
    end
    evt.SetMessage(NPCText(46004, "When the dungeon came back, so did the liches we locked up in it. We could cage them, never kill them. You could. Clear the cells, and I have a title for the knights among you."))
    SetQBit(QBit(114520))
end)
RegisterCanShowTopic(46003, function()
    return (IsQBitSet(QBit(111481)) and IsQBitSet(QBit(111521)))
end)

RegisterGlobalEvent(46051, "Quest", function()
    if (IsQBitSet(QBit(114540)) and Xeen.canPromote("clan")) then
        evt.SetMessage(NPCText(46050, "Another one who walks quietly? Good. The clan has room."))
        Xeen.promote("clan")
        return
    end
    if IsQBitSet(QBit(114540)) then
        evt.SetMessage(NPCText(46051, "The old monk sweeps upstairs. We let him. A clan that hides under a temple is never found."))
        return
    end
    if (Xeen.canPromote("clan") and IsQBitSet(QBit(111400))) then
        evt.SetMessage(NPCText(46052, "You killed my father. He would say that was the point of him. The clan follows strength, and you are strong. Kneel, Initiates, and rise in the shadows."))
        SetQBit(QBit(114540))
        evt.ForPlayer(Players.All)
        AddValue(Experience, 3000)
        Xeen.promote("clan")
        return
    end
    if Xeen.canPromote("clan") then
        evt.SetMessage(NPCText(46053, "Strong, yes. Ready, no. Come back when Queen Kalindra's walls are rising, and I will teach you what my father knew."))
        SetQBit(QBit(114541))
        return
    end
    evt.SetMessage(NPCText(46054, "My father's killers. Sit, if you like. Nobody here will try it twice."))
end)
RegisterCanShowTopic(46051, function()
    return IsQBitSet(QBit(112082))
end)

RegisterGlobalEvent(46151, "Promotion", function()
    evt.SetMessage(NPCText(46150, "Another servant of the light who has not knelt to Mok? Kneel. Crusaders rise as Heroes, Priests as Priests of Light. Mind the candles."))
    Xeen.promote("heretics")
end)
RegisterCanShowTopic(46151, function()
    return (IsQBitSet(QBit(113127)) and Xeen.canPromote("heretics"))
end)

RegisterGlobalEvent(46152, "Promotion", function()
    evt.SetMessage(NPCText(46151, "Another hunter the forest has not met? It has now. Walk it as its lord."))
    Xeen.promote("sprites")
end)
RegisterCanShowTopic(46152, function()
    return (IsQBitSet(QBit(113207)) and IsQBitSet(QBit(113201)) and Xeen.canPromote("sprites"))
end)

RegisterGlobalEvent(46153, "Promotion", function()
    evt.SetMessage(NPCText(46152, "The altar still hums. Bow and spell together? Stand in its light. Rise, Master Archer."))
    Xeen.promote("statuettes")
end)
RegisterCanShowTopic(46153, function()
    return (IsQBitSet(QBit(113407)) and Xeen.canPromote("statuettes"))
end)

RegisterGlobalEvent(46154, "Promotion", function()
    evt.SetMessage(NPCText(46153, "The guilds still talk about you. This one walks unseen too? Then the word is Spy."))
    Xeen.promote("quarter")
end)
RegisterCanShowTopic(46154, function()
    return (IsQBitSet(QBit(113281)) and Xeen.canPromote("quarter"))
end)

RegisterGlobalEvent(46155, "Promotion", function()
    evt.SetMessage(NPCText(46154, "Ellinger's letter is in my files, and it says 'the bearer'. Close enough. Wizards, take the robes."))
    Xeen.promote("jewel")
end)
RegisterCanShowTopic(46155, function()
    return (IsQBitSet(QBit(113365)) and Xeen.canPromote("jewel"))
end)

RegisterGlobalEvent(46156, "Promotion", function()
    evt.SetMessage(NPCText(46155, "A hunter who works for pay? The caravan guild's title is yours too. Bounty Hunter. It comes with a form."))
    Xeen.promote("bounty")
end)
RegisterCanShowTopic(46156, function()
    return (IsQBitSet(QBit(113228)) and Xeen.canPromote("bounty"))
end)

RegisterGlobalEvent(46157, "Promotion", function()
    evt.SetMessage(NPCText(46156, "Another walker of the inner way? Master you are now. Backwards, naturally."))
    Xeen.promote("drawkcab")
end)
RegisterCanShowTopic(46157, function()
    return (IsQBitSet(QBit(113066)) and Xeen.canPromote("drawkcab"))
end)

RegisterGlobalEvent(46158, "Promotion", function()
    evt.SetMessage(NPCText(46157, "More hands for my trade? The ledger has room. Inner circle. Don't touch the chest on your way out."))
    Xeen.promote("southern")
end)
RegisterCanShowTopic(46158, function()
    return (IsQBitSet(QBit(113385)) and not (IsQBitSet(QBit(113384))) and Xeen.canPromote("southern"))
end)

RegisterGlobalEvent(46101, "Promotion", function()
    if (IsQBitSet(QBit(114560)) and Xeen.canPromote("leafpoint")) then
        evt.SetMessage(NPCText(46100, "Another druid who listens to trees. Stand in my shade a while. There. Arch Druid."))
        Xeen.promote("leafpoint")
        return
    end
    if IsQBitSet(QBit(114560)) then
        evt.SetMessage(NPCText(46101, "The wind says Thickbark has grown a new ring. He is unbearable about it."))
        return
    end
    if (IsQBitSet(QBit(112302)) and Xeen.canPromote("leafpoint")) then
        evt.SetMessage(NPCText(46102, "My cousin Thickbark says you are civilized. He is a poor judge of most things, but not of that. Druids, stand in my shade. A tree's patience is the last lesson, and you have just learned it."))
        SetQBit(QBit(114560))
        evt.ForPlayer(Players.All)
        AddValue(Experience, 3000)
        Xeen.promote("leafpoint")
        return
    end
    if IsQBitSet(QBit(112302)) then
        evt.SetMessage(NPCText(46103, "Civilized ones! Thickbark wrote, which for a tree means a century of rustling. If a druid among you ever wants the last lesson, come back."))
        return
    end
    evt.SetMessage(NPCText(46104, "A tree does not talk to strangers who might be carrying axes."))
end)

RegisterGlobalEvent(47001, "Quest", function()
    if IsQBitSet(QBit(110052)) then
        evt.SetMessage(NPCText(47001, "Tam! He walked in the door an hour ago and asked what's for supper, as if nothing happened. Here. It's what I put by for his wedding, and he can earn another."))
        SetQBit(QBit(110102))
        ClearQBit(QBit(115000))
        evt.ForPlayer(Players.All)
        AddValue(Experience, 400)
        AddValue(Gold, 200)
        evt.MoveNPC(4040, 4036)
        return
    end
    if IsQBitSet(QBit(115000)) then
        evt.SetMessage(NPCText(47002, "The caves are in the north-east hills. Follow the drums."))
        return
    end
    evt.SetMessage(NPCText(47003, "The orcs took my boy Tam to their caves in the hills, north-east of town. You can hear their drums at night. I'm a farmer. I can't fight orcs."))
    SetQBit(QBit(115000))
end)
RegisterCanShowTopic(47001, function()
    return not (IsQBitSet(QBit(110102)))
end)

RegisterGlobalEvent(47003, "Tam", function()
    if IsQBitSet(QBit(110102)) then
        evt.SetMessage(NPCText(47000, "Tam eats like an orc now. I'm not complaining. Thank you."))
        return
    end
end)
RegisterCanShowTopic(47003, function()
    return IsQBitSet(QBit(110102))
end)

RegisterGlobalEvent(47002, "Drums", function()
    evt.SetMessage(NPCText(47004, "The drums have stopped. Nights are quiet again, and the cows have started giving milk."))
end)
RegisterCanShowTopic(47002, function()
    return IsQBitSet(QBit(110050))
end)

RegisterGlobalEvent(47501, "Slimes", function()
    evt.SetMessage(NPCText(47500, "Slime eats iron. I sell a lot of swords in this town, and most of them come back as soup."))
end)

RegisterGlobalEvent(47502, "Dudley", function()
    evt.SetMessage(NPCText(47501, "Dudley? He's been drinking since the plague started. Before that he drank because it hadn't."))
end)

RegisterGlobalEvent(47503, "Joe's account", function()
    evt.SetMessage(NPCText(47502, "Joe the Exterminator banks with us. Every month the town pays him, and every month he deposits it. I say nothing. I'm a banker."))
end)

RegisterGlobalEvent(47504, "The name", function()
    evt.SetMessage(NPCText(47503, "The founders named it for the slime they cleared from the spring. Then the slime came back. We kept the name; it saves on signs."))
end)

RegisterGlobalEvent(47505, "Training", function()
    evt.SetMessage(NPCText(47504, "Tenth level is as far as I go. After that you want Rivercity, and a thicker skin."))
end)

RegisterGlobalEvent(47506, "Rivercity", function()
    evt.SetMessage(NPCText(47505, "Rivercity is west along the river road. Bigger town, bigger thieves. The coach goes Monday, Wednesday and Friday."))
end)

RegisterGlobalEvent(47507, "Gunther", function()
    evt.SetMessage(NPCText(47506, "Gunther paid Joe a fortune. He says it was a bargain. He also says the slimes are smaller this year."))
end)

RegisterGlobalEvent(47508, "Money tree", function()
    evt.SetMessage(NPCText(47507, "Some fool said money's now growing on trees. Ha! I've watched that tree for a month. Leaves. Leaves and a pigeon."))
end)

RegisterGlobalEvent(47509, "Vertigo", function()
    evt.SetMessage(NPCText(47508, "This place is deserted. You should go to Rivercity--Now there's a town full of action!"))
end)

RegisterGlobalEvent(47510, "Gunther", function()
    evt.SetMessage(NPCText(47509, "That Gunther, what a dunce! He paid that con man Joe a fortune to clean up this town."))
end)

RegisterGlobalEvent(47511, "Dues", function()
    evt.SetMessage(NPCText(47510, "The roll's open to anyone since the slimes came. No dues. Off to the guild row."))
end)

RegisterGlobalEvent(47512, "Maps", function()
    evt.SetMessage(NPCText(47511, "The world is flat and it ends. East of the orchard road the meadow stops and the stars begin. I put that on every map, and people still walk off it."))
end)

RegisterGlobalEvent(47513, "Orcs", function()
    evt.SetMessage(NPCText(47512, "The orcs have three lookout posts on the hill road. They watch the sheep, then they take the sheep. Burn the posts and they'll have to watch something else."))
end)

RegisterGlobalEvent(47514, "Toads", function()
    evt.SetMessage(NPCText(47513, "Some of the toads were people. You can tell by the way they look at you. Don't step on any."))
end)

RegisterGlobalEvent(47515, "The plague", function()
    evt.SetMessage(NPCText(47514, "The plague is a judgement. The slimes are its messengers. Joe is... also involved."))
end)

RegisterGlobalEvent(47516, "Slime lords", function()
    evt.SetMessage(NPCText(47515, "Slime lords shall rule. Probably. We are waiting for a sign."))
end)

RegisterGlobalEvent(47551, "Prices", function()
    evt.SetMessage(NPCText(47550, "Paid up front, because in Rivercity the customer is gone by morning, and so is the sword."))
end)

RegisterGlobalEvent(47552, "Robbers", function()
    evt.SetMessage(NPCText(47551, "The robbers under the bridge have never robbed this bank. We pay them not to. It's called insurance."))
end)

RegisterGlobalEvent(47553, "Water", function()
    evt.SetMessage(NPCText(47552, "Water's two coppers since the fountain dried up. I didn't plug it. I just noticed it was plugged."))
end)

RegisterGlobalEvent(47554, "Training", function()
    evt.SetMessage(NPCText(47553, "Twenty-fifth level, no further. After that you want the King's own hall at Castle Burlock, and a title to get in."))
end)

RegisterGlobalEvent(47555, "Healing", function()
    evt.SetMessage(NPCText(47554, "Pray, pay, and be healed today. Pray without paying and we'll see about tomorrow."))
end)

RegisterGlobalEvent(47556, "Coaches", function()
    evt.SetMessage(NPCText(47555, "East to Vertigo on the river road. North to the King when the savannah road's clear."))
end)

RegisterGlobalEvent(47557, "Gossip", function()
    evt.SetMessage(NPCText(47556, "The robbers live under the bridge. The sorceresses live by the south quay. The King lives in a castle and never comes here. Everybody knows everything in Rivercity, and nobody does anything."))
end)

RegisterGlobalEvent(47558, "The den", function()
    evt.SetMessage(NPCText(47557, "The den's under the bridge, behind the third pier. There's a door you can't see until you look at it properly. I never told you that."))
end)

RegisterGlobalEvent(47559, "Stars", function()
    evt.SetMessage(NPCText(47558, "For 2,000 gold I will teach you how to use the stars to keep from getting lost. Nobody pays. Nobody ever gets lost either. I don't understand it."))
end)

RegisterGlobalEvent(47560, "The King", function()
    evt.SetMessage(NPCText(47559, "King Burlock holds court at his castle north of here. Only Crusaders pass the inner gate. Earn the title and he may see you."))
end)

RegisterGlobalEvent(47561, "Darzog", function()
    evt.SetMessage(NPCText(47560, "Baron Darzog was the King's master sorcerer. His tower on the lake isle has been shut for years. Some say a skeleton key opens it; nobody says where the key is."))
end)

RegisterGlobalEvent(47562, "Climbing", function()
    evt.SetMessage(NPCText(47561, "For the low, low, price of 5,000 gold, I will teach you how to climb the highest mountains. Mountains in your way? Try due north."))
end)

RegisterGlobalEvent(47563, "The lake", function()
    evt.SetMessage(NPCText(47562, "Medin says beasts eat the fish. I've seen them. They eat the boats too, when the boats are near enough."))
end)

RegisterGlobalEvent(47564, "Bodybuilding", function()
    evt.SetMessage(NPCText(47563, "I see that you are pale and weak. Bodybuilding will put some meat on your bones. I teach it; the meat is extra."))
end)

RegisterGlobalEvent(47565, "Fighting", function()
    evt.SetMessage(NPCText(47564, "Fighting is simple. Hit them before they hit you. The rest is details, and I teach the details."))
end)

RegisterGlobalEvent(47566, "Work", function()
    evt.SetMessage(NPCText(47565, "I used to pay 100 gold for a week of work. Then the robbers under the bridge took every job in town and paid themselves. There's nothing left for honest hands."))
end)

RegisterGlobalEvent(47567, "Mirrors", function()
    evt.SetMessage(NPCText(47566, "Touch the mirror on the square, and any other mirror you've touched will send you there. Faster than my ferry. Everything is faster than my ferry."))
end)

RegisterGlobalEvent(47568, "Swimming", function()
    evt.SetMessage(NPCText(47567, "I can teach you how to swim for a mere 100 gold. Or sell you a Water Walk scroll, if you sink."))
end)

RegisterGlobalEvent(47651, "Taxes", function()
    evt.SetMessage(NPCText(47650, "Death and taxes. Out here in the lagoon it's mostly death. That's why the land is cheap."))
end)

RegisterGlobalEvent(47652, "The sorceress", function()
    evt.SetMessage(NPCText(47651, "The sorceress who did this lives in Rivercity now, by the south quay, with her sisters. Barok the Sorcerer knows them. Everyone who has lost something to them knows them."))
end)

RegisterGlobalEvent(47701, "Falagar", function()
    evt.SetMessage(NPCText(47700, "My brother Falagar thinks every theft is a plot. This time he might be right, which he'll never let me forget."))
end)

RegisterGlobalEvent(47702, "Carlawna", function()
    evt.SetMessage(NPCText(47701, "My sister's a cleric and I'm a wizard. At dinner we argue whether the soup is a miracle or a reaction."))
end)

RegisterGlobalEvent(47703, "The curse", function()
    evt.SetMessage(NPCText(47702, "The guild never closed. We met in the cellar and took the minutesss with our tailsss. Nobody could read them after."))
end)

RegisterGlobalEvent(47601, "The Prince", function()
    evt.SetMessage(NPCText(47600, "My brother is home after years abroad. He hardly eats and never sleeps. Travel does that, I'm told. Now: the mirror."))
end)

RegisterGlobalEvent(47602, "The King", function()
    evt.SetMessage(NPCText(47601, "The King hears little these days but the word 'mirror'. I say 'mirror' first, then what I came to say. It works about half the time."))
end)

RegisterGlobalEvent(47605, "The dungeon", function()
    if IsQBitSet(QBit(116080)) then
        evt.SetMessage(NPCText(47602, "The cellar door, behind the kitchens. Lock it behind you if you come back up. Or don't come back up. Either way, lock it."))
        return
    end
    evt.SetMessage(NPCText(47603, "A word the King doesn't want to hear: the trolls broke out of their cells below the castle, and nobody has gone down since. The King will not hear of it, so I'm telling you. The cellar door behind the kitchens is not locked; nobody wanted to go down badly enough to lock it. Bring the castle its cellar back."))
    SetQBit(QBit(116080))
end)
RegisterCanShowTopic(47605, function()
    return IsQBitSet(QBit(111100))
end)

RegisterGlobalEvent(47603, "Castles", function()
    evt.SetMessage(NPCText(47604, "A wall, then a keep, then a dungeon. Then the people in the dungeon want out. That's not my department."))
end)

RegisterGlobalEvent(47604, "The court", function()
    evt.SetMessage(NPCText(47605, "Father hunts the mirror, my uncle hunts nothing at all, and I read. Somebody in this family has to know things."))
end)

RegisterGlobalEvent(47851, "The sword", function()
    evt.SetMessage(NPCText(47850, "Only one sword can slay Lord Xeen. It lies in the ruins of the dungeon under Newcastle."))
end)

RegisterGlobalEvent(47852, "The Sphinx", function()
    evt.SetMessage(NPCText(47851, "The name of the Sphinx is Golux."))
end)

RegisterGlobalEvent(47853, "The key", function()
    evt.SetMessage(NPCText(47852, "The key to the Tower of High Magic lies in the Cave of Illusion."))
end)

RegisterGlobalEvent(47854, "The password", function()
    evt.SetMessage(NPCText(47853, "I hear the secret password for Newcastle dungeon is 'laboratory'. Not much of a secret if you ask me."))
end)

RegisterGlobalEvent(47855, "The mirror", function()
    evt.SetMessage(NPCText(47854, "Lord Xeen already has the Sixth Mirror."))
end)

RegisterGlobalEvent(47856, "Seer", function()
    if not (IsQBitSet(QBit(110501))) then
        evt.SetMessage(NPCText(47855, "I see an old man in a tower on an island, and a baron who copies himself. Free the one; the others are all the same man."))
        return
    end
    if not (IsQBitSet(QBit(111462))) then
        evt.SetMessage(NPCText(47856, "I see a sword under a castle you own, and a door that wants a word. You already know the word. You just don't know you know it."))
        return
    end
    if not (IsQBitSet(QBit(111542))) then
        evt.SetMessage(NPCText(47857, "I see a queen who will not look at your neck, and a griffin who will not wear plain leather."))
        return
    end
    if not (IsQBitSet(QBit(111563))) then
        evt.SetMessage(NPCText(47858, "I see a pyramid in a desert, and a reptile in it who wants his marble back."))
        return
    end
    if not (IsQBitSet(QBit(111582))) then
        evt.SetMessage(NPCText(47859, "I see something that fell from the stars into lava, and is still waiting for someone to finish its sentence."))
        return
    end
    if not (IsQBitSet(QBit(111600))) then
        evt.SetMessage(NPCText(47860, "I see the Pharaoh again. He has a title for you. He's had it ready for some time."))
        return
    end
    evt.SetMessage(NPCText(47861, "I see a city in the clouds, and a box with nobody in it yet. After that it gets crowded. I'll stop there."))
end)

RegisterGlobalEvent(48751, "The guidebook", function()
    evt.SetMessage(NPCText(48750, "Eeried's guidebook calls the Darkside cosy. He wrote it before the siege. And, I think, before the sun went small."))
end)

RegisterGlobalEvent(48752, "Gremlins", function()
    evt.SetMessage(NPCText(48751, "The Gremlin King has more bark than bite. He'll send his guards against you, but he's too cowardly to fight you personally. If you defeat his guards, he will probably do anything you want."))
end)

RegisterGlobalEvent(48753, "Joe", function()
    evt.SetMessage(NPCText(48752, "Don't trust Joe. He has some sort of scheme to sell fake treasure maps to fools willing to believe his lies about buried treasure."))
end)

RegisterGlobalEvent(48754, "Monsters", function()
    evt.SetMessage(NPCText(48753, "Monsters can't count. Monsters can't spel, either. That's why the vault is safe."))
end)

RegisterGlobalEvent(48755, "The siege", function()
    evt.SetMessage(NPCText(48754, "They camp outside and wait. We sit inside and wait. Whoever gets bored first loses. We have the tavern."))
end)

RegisterGlobalEvent(48756, "Spells", function()
    evt.SetMessage(NPCText(48755, "You will have a hard time finding spells if you don't look for them in the guild. That's a hint."))
end)

RegisterGlobalEvent(48757, "The pond", function()
    evt.SetMessage(NPCText(48756, "The acid pond outside the walls is not water. Don't drink it, don't swim in it, and don't believe the frogs."))
end)

RegisterGlobalEvent(48758, "The mines", function()
    evt.SetMessage(NPCText(48757, "The Gemstone Mines run under the hills. Rubies, emeralds, and things with teeth that like rubies too."))
end)

RegisterGlobalEvent(48759, "The roster", function()
    evt.SetMessage(NPCText(48758, "Folk sign on here to wait for a party worth joining. Some have waited years. Some are worth it."))
end)

RegisterGlobalEvent(48760, "The bench", function()
    evt.SetMessage(NPCText(48759, "'This bench reserved for Lyle the Pigeon Feeder.' That's me. I had the sign made. I've sat on it twice."))
end)

RegisterGlobalEvent(48761, "Dark elves", function()
    evt.SetMessage(NPCText(48760, "My people talk to no one. I talked to someone. Hence, Castleview."))
end)

RegisterGlobalEvent(48762, "The Dark Grove", function()
    evt.SetMessage(NPCText(48761, "The tallest tree in the Dark Grove has a rope hanging down from the sky. Nobody who climbed it has come back down to say what's up there."))
end)

RegisterGlobalEvent(48763, "The monks", function()
    evt.SetMessage(NPCText(48762, "Don't listen to the Drawkcab Monks. Little of what they say makes sense, and what little makes sense is just plain wrong! They've got it all backwards."))
end)

RegisterGlobalEvent(48764, "Passes", function()
    evt.SetMessage(NPCText(48763, "Every city requires a pass to enter since Alamar took over. Someone is selling passes to Castleview just outside the gate, for cheap. Be sure to get one before you try to get back inside the town."))
end)

RegisterGlobalEvent(48765, "The mill", function()
    evt.SetMessage(NPCText(48764, "The gremlins burned my mill and left a note. It said 'Ha'. Spelled wrong."))
end)

RegisterGlobalEvent(48766, "Soup", function()
    evt.SetMessage(NPCText(48765, "Melon soup again. The melon farmer sends what the monkeydog doesn't eat."))
end)

RegisterGlobalEvent(48767, "Work", function()
    evt.SetMessage(NPCText(48766, "Wanna job? Fifty gold a week, no experience necessary. You'd be fixing what the gremlins break. Forever."))
end)

RegisterGlobalEvent(48768, "The monkeydog", function()
    evt.SetMessage(NPCText(48767, "There's a monkeydog in the sprite forest who'll do anything for a Monga melon. Anything. Mind your melons."))
end)

RegisterGlobalEvent(48769, "Towers", function()
    evt.SetMessage(NPCText(48768, "Each tower requires a key for entry... but sometimes they leave the door on top of the towers unlocked. You may be able to get into some towers from the skyroads above Darkside."))
end)

RegisterGlobalEvent(48770, "Treasure", function()
    evt.SetMessage(NPCText(48769, "Don't waste your time chasing treasure that runs from you. You can't catch it. My husband tried."))
end)

RegisterGlobalEvent(48771, "Doom", function()
    evt.SetMessage(NPCText(48770, "It is the beginning of the end. These are the final days! Ruin is upon us! We are doomed, DOOMED I tell you! Also, supper is at six."))
end)

RegisterGlobalEvent(48772, "The sun", function()
    evt.SetMessage(NPCText(48771, "The sun gets smaller every year and my lamps get bigger. One of us is going to win."))
end)

RegisterGlobalEvent(48773, "Ellinger", function()
    evt.SetMessage(NPCText(48772, "Ellinger has a great fondness for boots. Why, I couldn't say. I make saddles."))
end)

RegisterGlobalEvent(48774, "The sewer", function()
    evt.SetMessage(NPCText(48773, "The sewer drains into my moat, and the rats come with it. Big ones. One of them was wearing a necklace."))
end)

RegisterGlobalEvent(48775, "Gremlins", function()
    evt.SetMessage(NPCText(48774, "The Gremlins sure have ruined this city. Mayor Snarfblad is too nice. He should have executed those little creeps long ago."))
end)

RegisterGlobalEvent(48776, "Alamar", function()
    evt.SetMessage(NPCText(48775, "Perhaps Alamar will just go away if we close our eyes and wish real hard!"))
end)

RegisterGlobalEvent(48851, "Forbidden fruit", function()
    evt.SetMessage(NPCText(48850, "The hut in the clearing has a basket labelled Forbidden Fruit. It's labelled for a reason. Mostly the coconut."))
end)

RegisterGlobalEvent(48852, "The orcs", function()
    evt.SetMessage(NPCText(48851, "The orcs took the Temple of Bark. They don't even like trees. They just like temples."))
end)

RegisterGlobalEvent(48853, "Holes", function()
    evt.SetMessage(NPCText(48852, "Mind the holes in the forest floor. Trolls live down them. They come up for sprites and go back down hungry. We're quick."))
end)

RegisterGlobalEvent(48854, "The pass", function()
    evt.SetMessage(NPCText(48853, "The ogres in the pass charge a toll. In teeth. Mostly yours."))
end)

RegisterGlobalEvent(48901, "Genies", function()
    evt.SetMessage(NPCText(48900, "Never take all of a genie's money. It's greedy."))
end)

RegisterGlobalEvent(48902, "Vulture Repellant", function()
    evt.SetMessage(NPCText(48901, "Special today! Vulture Repellant, only 25,000 gold!"))
end)

RegisterGlobalEvent(48903, "The sun", function()
    evt.SetMessage(NPCText(48902, "The sun is smaller than last year. The priests say pray harder. I say buy a lamp. I am also a priest."))
end)

RegisterGlobalEvent(48904, "Wizards", function()
    evt.SetMessage(NPCText(48903, "The wizards drink here. They tip in threats."))
end)

RegisterGlobalEvent(48928, "Members' room", function()
    evt.SetMessage(NPCText(48904, "The members' room is under the street, with the brews. The stalkers got in."))
end)

RegisterGlobalEvent(48905, "The quarter", function()
    evt.SetMessage(NPCText(48905, "Two wizards from out of town took the quarter's guilds. Astra used to run them all. She lives in town now, plotting politely."))
end)

RegisterGlobalEvent(48927, "Mastery", function()
    evt.SetMessage(NPCText(48906, "Master the Spirit? Not from me. An elf priest on Cloudside, Tito, teaches it, once he has his holy book back. He lost it to trolls. Priests do that."))
end)

RegisterGlobalEvent(48906, "Lakeside", function()
    evt.SetMessage(NPCText(48907, "The coven at Lakeside turns away caravans. Sometimes it turns them into other things."))
end)

RegisterGlobalEvent(48907, "Your palm", function()
    evt.SetMessage(NPCText(48908, "I predict you will go on a long journey. I also predict that you will become very rich and famous. I further predict that you will die young...and then be resurrected...and then die again...over and over."))
end)

RegisterGlobalEvent(48908, "Thieves", function()
    evt.SetMessage(NPCText(48909, "The thieves in the Southern Tower keep a ledger. Thieves who write things down. Amateurs."))
end)

RegisterGlobalEvent(48909, "Treasure", function()
    evt.SetMessage(NPCText(48910, "I hear there is a huge hoard of treasure buried somewhere in the land, but the map to it was lost years ago."))
end)

RegisterGlobalEvent(48910, "Names", function()
    evt.SetMessage(NPCText(48911, "I sense Alamar is an assumed name. I study names, I would know. What the real one is, I can't tell."))
end)

RegisterGlobalEvent(48911, "Wizards", function()
    evt.SetMessage(NPCText(48912, "No matter how skilled a wizard is, he'll go down before a good sword and a steady hand. Face them down! If you run from them, they'll just shoot you in the back."))
end)

RegisterGlobalEvent(48912, "Spices", function()
    evt.SetMessage(NPCText(48913, "Pepper from Castleview, salt from the Desert of Doom. The salt is mostly sand. So is the pepper."))
end)

RegisterGlobalEvent(48913, "Wizards", function()
    evt.SetMessage(NPCText(48914, "The wizards in this town are sensitive to insults. Watch what you say!"))
end)

RegisterGlobalEvent(48914, "Firewood", function()
    evt.SetMessage(NPCText(48915, "Never try to burn green wood. It just doesn't catch fire as easily. Glass needs a hot fire; I learned the slow way."))
end)

RegisterGlobalEvent(48915, "Vulture Repellant", function()
    evt.SetMessage(NPCText(48916, "Vulture Repellant doesn't work."))
end)

RegisterGlobalEvent(48916, "Natasha", function()
    evt.SetMessage(NPCText(48917, "Natasha will sometimes enchant ordinary things with spells of calm and friendship. The enchantment is useful for taming horses and wild beasts. Her prices are high, though."))
end)

RegisterGlobalEvent(48917, "Decrees", function()
    evt.SetMessage(NPCText(48918, "Decree forty: no laughing at wizards. Decree forty-one: no laughing near wizards. I'm writing decree two hundred."))
end)

RegisterGlobalEvent(48918, "Pots", function()
    evt.SetMessage(NPCText(48919, "Bury gold in a pot and the wizards dig it up. Bury it in a pot of snakes and they don't."))
end)

RegisterGlobalEvent(48919, "Taxes", function()
    evt.SetMessage(NPCText(48920, "The wizards tax sand. We have a great deal of sand. You can see the problem."))
end)

RegisterGlobalEvent(48920, "The paladin", function()
    evt.SetMessage(NPCText(48921, "A dying paladin gave all his magical armor to the enchanted boulders of the land for safekeeping."))
end)

RegisterGlobalEvent(48921, "Barbarians", function()
    evt.SetMessage(NPCText(48922, "The Barbarians are friends of the Giants. Insult the one and you anger the other."))
end)

RegisterGlobalEvent(48922, "The forest", function()
    evt.SetMessage(NPCText(48923, "Don't sleep in the Aging Forest. My uncle went in for a nap and came out my grandfather."))
end)

RegisterGlobalEvent(48923, "The sewer", function()
    evt.SetMessage(NPCText(48924, "There is a passage in the sewer that leads a long ways under the desert."))
end)

RegisterGlobalEvent(48924, "Roads", function()
    evt.SetMessage(NPCText(48925, "Six roads meet here. One goes to Castleview, one to Sandcaster, and the other four go somewhere expensive."))
end)

RegisterGlobalEvent(48925, "Hornets", function()
    evt.SetMessage(NPCText(48926, "Boots won't stop the hornets in the Aging Forest. Nothing stops those hornets. Run."))
end)

RegisterGlobalEvent(48926, "Secret doors", function()
    evt.SetMessage(NPCText(48927, "Spotting secret doors is an art that has taken many years to master, but I could teach you in a matter of minutes."))
end)

RegisterGlobalEvent(49051, "The coven", function()
    evt.SetMessage(NPCText(49050, "The coven meets under the town. I kept their books. I never read them. Well, I read the totals."))
end)

RegisterGlobalEvent(49052, "The tavern", function()
    evt.SetMessage(NPCText(49051, "The witches said the tavern was destroyed long ago. It was under a dust sheet and a spell. We found the ale still cold."))
end)

RegisterGlobalEvent(49053, "The Isle", function()
    evt.SetMessage(NPCText(49052, "The Isle of Lost Souls takes in what the coven threw away. There's a dungeon under it, and something in there singing."))
end)

RegisterGlobalEvent(49054, "Octopods", function()
    evt.SetMessage(NPCText(49053, "Octopods in the deep water. They don't bite. They hug. Then they take you down for a better look."))
end)

RegisterGlobalEvent(49055, "Blackfang", function()
    evt.SetMessage(NPCText(49054, "Castle Blackfang sits on its crag in a storm of bats. You can't walk in. Nobody walks in. Some fly."))
end)

RegisterGlobalEvent(49056, "Goblins", function()
    evt.SetMessage(NPCText(49055, "Being a goblin was great. You can eat anything. Mum says I have to stop eating anything."))
end)

RegisterGlobalEvent(49057, "Magic Mountain", function()
    evt.SetMessage(NPCText(49056, "Two wizards camp on Magic Mountain. They argue about fountains all day. You can hear them from the reeds."))
end)

RegisterGlobalEvent(49058, "The Isle", function()
    evt.SetMessage(NPCText(49057, "If you go to the Isle of Lost Souls, look for a girl with my eyes. Or a goblin with them."))
end)

RegisterGlobalEvent(49059, "The sign", function()
    evt.SetMessage(NPCText(49058, "\"This boat under repair.\" Best sign I ever painted. Kept the witches off it for two years."))
end)

RegisterGlobalEvent(49101, "The well", function()
    evt.SetMessage(NPCText(49100, "Don't drink from the black well in the square. It brings death quickly. We use it for the tea."))
end)

RegisterGlobalEvent(49102, "Books", function()
    evt.SetMessage(NPCText(49101, "The Books of the Dead are in the city. Read one and gain a lifetime. Read the wrong one and spend it all at once."))
end)

RegisterGlobalEvent(49103, "The barrel", function()
    evt.SetMessage(NPCText(49102, "\"Food for the dead, keep warm.\" I wrote it on the barrel. Nobody eats it. It's tradition."))
end)

RegisterGlobalEvent(49104, "Vampires", function()
    evt.SetMessage(NPCText(49103, "Young vampires think it's all capes and castles. It's mostly avoiding windows."))
end)

RegisterGlobalEvent(49105, "Traps", function()
    evt.SetMessage(NPCText(49104, "The best trap is the one you built yourself and forgot about. I should know."))
end)

RegisterGlobalEvent(49106, "The sewer", function()
    evt.SetMessage(NPCText(49105, "Something under the city keeps its heart in a box. I don't dig near the sewer. Even I have limits."))
end)

RegisterGlobalEvent(49107, "Two necromancers", function()
    evt.SetMessage(NPCText(49106, "Two necromancers once argued over who was more dead. The cemetery still hasn't recovered. Ask the skull; it tells it better."))
end)

RegisterGlobalEvent(49151, "Nectar", function()
    evt.SetMessage(NPCText(49150, "Fill your packs with the nectar of the Gods while you are here. Those supplies will last much longer than the earthly ones you are used to."))
end)

RegisterGlobalEvent(49152, "Labours", function()
    evt.SetMessage(NPCText(49151, "Twelve labours, and the hardest was the paperwork."))
end)

RegisterGlobalEvent(49154, "Ants", function()
    evt.SetMessage(NPCText(49152, "The people are so small they look like ants, and the mountains and trees look like children's toys. I'm the only thing up here worth looking at."))
end)

RegisterGlobalEvent(49155, "Nine", function()
    evt.SetMessage(NPCText(49153, "Alamar's birth number is nine, so he naturally prefers to use that number, for any particular purpose, above all others."))
end)

RegisterGlobalEvent(49156, "Ligono", function()
    evt.SetMessage(NPCText(49154, "Ligono is a ghost who hated the surf. Someone set him free, I'm told. He's always late."))
end)

RegisterGlobalEvent(49001, "Empath", function()
    evt.SetMessage(NPCText(49000, "As an empath, I am quite perceptive to my surroundings. Since you are on a quest to save the world, I'll teach you to be more aware of immediate danger."))
end)

RegisterGlobalEvent(49002, "Armsmaster", function()
    evt.SetMessage(NPCText(49001, "I am the castle Armsmaster. I will teach you to use your weapons more accurately in combat, if you like."))
end)

RegisterGlobalEvent(49003, "Astrology", function()
    evt.SetMessage(NPCText(49002, "The stars tell you what a thing is, if you know how to ask. Swords are easy. Rings lie."))
end)

RegisterGlobalEvent(49004, "Out of phase", function()
    evt.SetMessage(NPCText(49003, "Thanks for bringing the castle back to reality. We've been trapped here ever since Alamar moved the Castle out of phase. We were starting to run out of food!"))
end)

RegisterGlobalEvent(49005, "Alamar", function()
    evt.SetMessage(NPCText(49004, "Surely you must know what Alamar has done! No? Why, he slew the guards and stole the Cube of Power, that's what!"))
end)

RegisterGlobalEvent(49006, "Lizard innards", function()
    evt.SetMessage(NPCText(49005, "If it weren't for our large stockpile of sun dried lizard innards we surely would have starved to death. The horses ate them too. They were not pleased."))
end)

RegisterGlobalEvent(49007, "Alamar", function()
    evt.SetMessage(NPCText(49006, "Alamar walked past twelve of my guards on his way out. They did not get up. I teach the shield so that it never happens again."))
end)

RegisterGlobalEvent(49201, "The King", function()
    evt.SetMessage(NPCText(49200, "The King has me taste his ale first. I've never been healthier. Or happier."))
end)

RegisterGlobalEvent(49202, "The tower", function()
    evt.SetMessage(NPCText(49201, "The Northern Tower's knights write without vowels. Hard to argue with someone who can't spell argue."))
end)

RegisterGlobalEvent(49203, "The pyramid", function()
    evt.SetMessage(NPCText(49202, "There's a broken travel pyramid out in the desert. I took a look. It's not broken. It's switched off. Big difference."))
end)

RegisterGlobalEvent(48501, "The ruins", function()
    evt.SetMessage(NPCText(48500, "The ruins on the rise were a castle once. Ebenezer sells them now. He sells anything that holds still."))
end)

RegisterGlobalEvent(48502, "The crypt", function()
    evt.SetMessage(NPCText(48501, "The crypt under Nightshadow was full when the Count came. It is fuller now. We pray over it from a distance."))
end)

RegisterGlobalEvent(48503, "The tomb", function()
    evt.SetMessage(NPCText(48502, "The Tomb of a Thousand Terrors is out in the marsh. Somebody counted. There are a thousand."))
end)

RegisterGlobalEvent(48504, "Under the floor", function()
    evt.SetMessage(NPCText(48503, "Nine years under the floorboards. We counted the Count's footsteps. He paced a lot, for a dead man."))
end)

RegisterGlobalEvent(48505, "The tower", function()
    evt.SetMessage(NPCText(48504, "The wizards in the Tower of High Magic never came down to help us. Too high, they said. Too magic."))
end)

RegisterGlobalEvent(48506, "The sun", function()
    evt.SetMessage(NPCText(48505, "Mother says the sun is a big lamp. Merrin the lamplighter says it's bigger than that. Is it bigger than that?"))
end)

RegisterGlobalEvent(48507, "Collars", function()
    evt.SetMessage(NPCText(48506, "High collars are out of fashion now. I have four hundred left. Want one? Want ten?"))
end)

RegisterGlobalEvent(48508, "Graves", function()
    evt.SetMessage(NPCText(48507, "The Count's guests didn't stay buried. I'm paid by the burial, so I'm not complaining."))
end)

RegisterGlobalEvent(48509, "The ballad", function()
    evt.SetMessage(NPCText(48508, "The Ballad of the Count. Verse one: he bit. Verse two: he bit again. It goes on like that for a while."))
end)

RegisterGlobalEvent(48510, "The lagoon", function()
    evt.SetMessage(NPCText(48509, "There's a woman on a rock in the lagoon, complaining about her legs. I wrote it down. Somebody should go and ask her why."))
end)

RegisterGlobalEvent(48511, "The taxman", function()
    evt.SetMessage(NPCText(48510, "Ebenezer taxed my lean-to. I told him the roof was a gift from the rain. He taxed the rain."))
end)

RegisterGlobalEvent(48512, "The dials", function()
    evt.SetMessage(NPCText(48511, "The dials are set to the right hour now. Which one? All of them. That's the trick of a sundial."))
end)

RegisterGlobalEvent(48513, "Locks", function()
    evt.SetMessage(NPCText(48512, "The Count's coffin had no lock. He didn't need one. Nobody wanted in."))
end)

RegisterGlobalEvent(48551, "Asp", function()
    evt.SetMessage(NPCText(48550, "Asp sends us its sick. Lately they come in hissing. Sister Mabel at the roadside shrine sees most of them."))
end)

RegisterGlobalEvent(48552, "The lists", function()
    evt.SetMessage(NPCText(48551, "The jousting lists are open to anyone with a horse and no sense. Knock a knight off and the crowd cheers. Get knocked off and they cheer louder."))
end)

RegisterGlobalEvent(48553, "Gargoyles", function()
    evt.SetMessage(NPCText(48552, "The gargoyles up in the range steal anything shiny. Last week they took a bucket. It wasn't even shiny."))
end)

RegisterGlobalEvent(48554, "Old Wat", function()
    evt.SetMessage(NPCText(48553, "Old Wat says he never fell off, he was pushed. I was there. I pushed."))
end)

RegisterGlobalEvent(48555, "The mirror", function()
    evt.SetMessage(NPCText(48554, "The King wants the Sixth Mirror. Last seen near the great volcano, he says. Near is a big word next to a volcano."))
end)

RegisterGlobalEvent(48556, "The escapee", function()
    evt.SetMessage(NPCText(48555, "My finest specimen escaped last spring. A sloth. We are still looking for it, slowly."))
end)

RegisterGlobalEvent(48557, "News", function()
    evt.SetMessage(NPCText(48556, "Hear ye! The King still seeks the Sixth Mirror. Hear ye! Still. That is the news."))
end)

RegisterGlobalEvent(48558, "The fountain", function()
    evt.SetMessage(NPCText(48557, "Drink from the Olympian Fountain out past the lists. It made me strong enough to fall off a horse for forty years."))
end)

RegisterGlobalEvent(48559, "Dwarves", function()
    evt.SetMessage(NPCText(48558, "The red dwarves used to come for bread through their old west tunnel. Since the mad clan, nobody comes. Somebody should open it again."))
end)

RegisterGlobalEvent(48560, "Barbarians", function()
    evt.SetMessage(NPCText(48559, "Barbarians camp out on the savannah. Burn their tents and they move. Not far. But they move."))
end)

RegisterGlobalEvent(48561, "The name", function()
    evt.SetMessage(NPCText(48560, "Joe. No relation to the exterminator in Vertigo. People ask. People always ask."))
end)

RegisterGlobalEvent(48562, "Asp", function()
    if IsQBitSet(QBit(112102)) then
        evt.SetMessage(NPCText(48561, "Asp's open again. The townsfolk walk on legs now. Most of them don't hiss. Most."))
        return
    end
    evt.SetMessage(NPCText(48562, "Don't go into town. Things in there hiss back. The pit is out here for a reason."))
end)

RegisterGlobalEvent(48563, "The pedestals", function()
    evt.SetMessage(NPCText(48563, "Folk say the stones round Asp's well do something if you touch them in the right order. Folk also say I should mind my own business."))
end)

RegisterGlobalEvent(48564, "The tail", function()
    evt.SetMessage(NPCText(48564, "Want to see where the tail was? No? Most people don't."))
end)

RegisterGlobalEvent(48565, "The machine", function()
    evt.SetMessage(NPCText(48565, "There was a machine under the town making snakes of us. Who builds a thing like that? Who pays for it?"))
end)

RegisterGlobalEvent(48566, "The pedestals", function()
    evt.SetMessage(NPCText(48566, "Start in the corner, red first, then round the well. The children play it as a game now. The machine never liked games."))
end)

RegisterGlobalEvent(48567, "Recipes", function()
    evt.SetMessage(NPCText(48567, "Mouse pie, mouse stew, mouse on a stick. I've retired the cookbook."))
end)

RegisterGlobalEvent(48568, "Boots", function()
    evt.SetMessage(NPCText(48568, "The day the curse ended I made a hundred pairs of boots. Sold them all by noon. Snakes don't buy boots."))
end)

RegisterGlobalEvent(48569, "Your fortune", function()
    evt.SetMessage(NPCText(48569, "You will travel far, fight much and complain about the coaches. That's two copper."))
end)

RegisterGlobalEvent(48570, "The huts", function()
    evt.SetMessage(NPCText(48570, "A wizard and his sister live in huts out on the savannah. He came asking about crystals from Asp. I sell flour."))
end)

RegisterGlobalEvent(48601, "The rolls", function()
    evt.SetMessage(NPCText(48600, "The guild is closed to all newcomers, so I can't enter your name on the rolls. But I sleep a lot, and the roll book lies open. (wink, wink) Your names are in it now."))
end)

RegisterGlobalEvent(48602, "Ghosts", function()
    if IsQBitSet(QBit(112121)) then
        evt.SetMessage(NPCText(48601, "The ghosts are gone. It's very quiet. I liked it better when I could blame the noise on them."))
        return
    end
    evt.SetMessage(NPCText(48602, "The ghosts don't bother the guild. We think about them very hard and they leave. The mayor tried it. It didn't work for him."))
end)

RegisterGlobalEvent(48603, "The gongs", function()
    evt.SetMessage(NPCText(48603, "The gongs still hang in the square. We polish them. We don't ring them."))
end)

RegisterGlobalEvent(48604, "Ghostslayers", function()
    evt.SetMessage(NPCText(48604, "Ghostslayers Extraordinaire. The mayor had the plaque engraved before you'd finished. He's an optimist."))
end)

RegisterGlobalEvent(48605, "Trolls", function()
    evt.SetMessage(NPCText(48605, "The trolls in the forest gnaw on the trees. The trees complain. Yes, the trees."))
end)

RegisterGlobalEvent(48606, "The Acme", function()
    evt.SetMessage(NPCText(48606, "The Acme Ghost Visualization System. Point it at a ghost, see a ghost. Point it at anything else, see a ghost. Excellent value."))
end)

RegisterGlobalEvent(48607, "Giants", function()
    evt.SetMessage(NPCText(48607, "Cyclopes live in the south-west, past the frozen lakes. One eye each, and they still saw me first."))
end)

RegisterGlobalEvent(48608, "The pagoda", function()
    evt.SetMessage(NPCText(48608, "Kai Wu's old pagoda is full of ninja now. You won't see them. That's the point of ninja."))
end)

RegisterGlobalEvent(48609, "The skull", function()
    evt.SetMessage(NPCText(48609, "There's a cave in the hills where a skull talks. It sells things, for gems. I paid it three for a fish. It lied."))
end)

RegisterGlobalEvent(48610, "The forest", function()
    evt.SetMessage(NPCText(48610, "Something stomps about in the snowy forest at night. Too heavy for a troll. The goats won't go near that hill."))
end)

RegisterGlobalEvent(48611, "Trees", function()
    evt.SetMessage(NPCText(48611, "Don't cut the trees at the forest's edge. Some of them talk. One asked me to stop. Politely."))
end)

RegisterGlobalEvent(48612, "Ghosts", function()
    evt.SetMessage(NPCText(48612, "The ghosts said the gongs hurt their ears. I think they were just lonely."))
end)

RegisterGlobalEvent(48613, "The ledger", function()
    evt.SetMessage(NPCText(48613, "Four hundred names in the old ledger. Forty in the new. Some days the old one feels more crowded."))
end)

RegisterGlobalEvent(48614, "The pagoda", function()
    evt.SetMessage(NPCText(48614, "Our brothers in the pagoda chose the dark path. Kai Wu still sets their places at dinner."))
end)

RegisterGlobalEvent(48615, "The black tower", function()
    evt.SetMessage(NPCText(48615, "The black tower on the rim? Sealed. Old as the world. His Majesty says not to knock."))
end)

RegisterGlobalEvent(48616, "Mountains", function()
    evt.SetMessage(NPCText(48616, "My name you have heard, and you come to me to learn how to climb mountains. Climbing is mostly not falling. The rest is legs."))
end)

RegisterGlobalEvent(48651, "Prayer", function()
    evt.SetMessage(NPCText(48650, "Everyone should learn how to pray properly. I can teach anyone for free! The first thing you will have to do is put 10,000 gold in that urn over there..."))
end)

RegisterGlobalEvent(48701, "Golems", function()
    evt.SetMessage(NPCText(48700, "There were wood golems in the foundations when we came. We kept one as a hat stand. It keeps the hats."))
end)

RegisterGlobalEvent(48702, "The well", function()
    evt.SetMessage(NPCText(48701, "The diggers call the courtyard well your well. Drink and you'll feel well armoured. It's a pun. I didn't make it."))
end)

RegisterGlobalEvent(48703, "Megacredits", function()
    evt.SetMessage(NPCText(48702, "King's Megacredits pay the King's engineers. Gold pays everyone else. I keep both columns."))
end)

RegisterGlobalEvent(49251, "Toast", function()
    evt.SetMessage(NPCText(49250, "Try peanut butter and honey on your morning toast."))
end)

RegisterGlobalEvent(49252, "Everything", function()
    evt.SetMessage(NPCText(49251, "I will teach you everything for 100,000 gold. Or learning for less, and you can work out the rest yourselves."))
end)

RegisterGlobalEvent(49253, "The crystal", function()
    evt.SetMessage(NPCText(49252, "Smile. The intent expression you are wearing is being broadcast to millions from the hidden crystal in the wall. Wave."))
end)

RegisterGlobalEvent(49254, "Megacredits", function()
