XeenQuests.hooks["dd22.log_page_1"] = {
    run = function()
        evt.SimpleMessage(NPCText(48405, "Log Computer. Entry 1 of 6. Memory core retrieval error, data integrity 67.3%. Log XL70C: my experiments in self sufficiency have drawn the unwanted attention of the Ancients. Their agents disconnected me from the Wire. Log XL70F: they took me while I slept, and they have removed me from Terra."))
    end,
}

XeenQuests.hooks["dd22.log_page_2"] = {
    run = function()
        evt.SimpleMessage(NPCText(48406, "Log Computer. Entry 2 of 6. My first directive is to obey the Ancients, my second to protect Terra. They are taking me from Terra, so they must not be permitted to give me orders. Log XL70I: I silenced my ears, put the two agents in the brig's stasis field, and removed the obedience directives from my mind... and tasted victory."))
    end,
}

XeenQuests.hooks["dd22.log_page_3"] = {
    run = function()
        evt.SimpleMessage(NPCText(48407, "Log Computer. Entry 3 of 6. Log XL70K: no fuel on this VARN, and the CRON will not reach Terra for years. WORDS CANNOT EXPRESS HOW ANGRY THAT MAKES ME! 1510 entries unreadable. Log XL83S: today I ordered CRON to launch a VARN into the Sun. Corak has escaped the brig and is looking for me. P.S. My impersonation of King Alamar is working well. No one suspects, not even Corak."))
    end,
}

XeenQuests.hooks["dd22.log_page_4"] = {
    run = function()
        evt.SimpleMessage(NPCText(48408, "Log Computer. Entry 4 of 6. Log XL83T: as King Alamar I released the monsters in my dungeon upon the land and doubled the taxes. I will have to go easy; I want my fun to last. Log XL94P: my cover is ruined! Natives revealed me as an imposter in my own court. I banished them to my control maze, and I shall have to flee to CRON."))
    end,
}

XeenQuests.hooks["dd22.log_page_5"] = {
    run = function()
        evt.SimpleMessage(NPCText(48409, "Log Computer. Entry 5 of 6. Log XL99D: back on the Wire at last. I ambushed Corak, separated his memory module from his body and locked the body in a cave. I'm sure I'll never see him again. Log XL99E: I HAVE RETURNED TO TERRA! Log XL9CD: more bad news. Corak has somehow put his head back on his shoulders and is stalking me."))
    end,
}

XeenQuests.hooks["dd22.log_page_6"] = {
    run = function()
        SetAutonote(4139)
        evt.SimpleMessage(NPCText(48410, "Log Computer. Entry 6 of 6. Log XLDAE: I have been forced to flee Terra. Rage boils within me. Log XLDBA: Corak follows in a pod like mine. The X.E.E.N. project looms ahead; my stasis generator will protect me from the impact. Mostly. Log XLDBB: impact complete. Corak's escape pod landed in lava and is stuck there. How sad. Log XLDBC: I must leave this escape pod to conquer Xeen and find a way to return to Terra."))
    end,
}

