        if (HasAward(Award(409)) and IsQBitSet(QBit(111740)) and IsQBitSet(QBit(111741)) and IsQBitSet(QBit(111742)) and IsQBitSet(QBit(111743))) then
            SetQBit(QBit(111763))
            evt.ForPlayer(Players.All)
            SetAward(Award(415))
            evt.ForPlayer(Players.All)
            AddValue(Experience, 10500)
            evt.StatusText(NPCText(41929, "Water Sleeper: I am awake and my confidence is at 100%. Grunfeld field generator is active and reports 100% confidence."), 6)
            return
        end
        if HasAward(Award(409)) then
            evt.StatusText(NPCText(41930, "Water Sleeper: I am awake and my confidence is at 100%. Awaiting Grunfeld field activation."), 6)
            return
        end
        evt.StatusText(NPCText(41931, "Water Sleeper: The Guardian has not informed me of your status as Chosen Ones. Much as I would like to, I am unable to fully awaken."), 6)
    end,
}

