XeenQuests.hooks["q-d16.throne"] = {
    run = function()
        if IsQBitSet(QBit(113322)) then
            evt.StatusText(NPCText(44805, "The bloody throne. Nothing left on it but the blood."), 5)
            return
        end
        if not ((IsQBitSet(QBit(113321)) or IsQBitSet(QBit(113323)) or IsQBitSet(QBit(113242)) or IsQBitSet(QBit(113244)))) then
            evt.StatusText(NPCText(44806, "A throne of black wood, big enough for four of you. Gurodel would notice."), 6)
            return
        end
        if IsQBitSet(QBit(113320)) then
            SetQBit(QBit(113322))
            evt.StatusText(NPCText(44807, "The bloody throne. Whatever the People had to give, they gave you in friendship."), 6)
            return
        end
        SetQBit(QBit(113322))
        AddValue(InventoryItem(12334), 12334)
        AddValue(InventoryItem(12334), 12334)
        evt.ForPlayer(Players.All)
        AddValue(Experience, 14000)
        evt.StatusText(NPCText(44808, "You search the bloody throne and find two energy disks."), 5)
    end,
}

