XeenQuests.hooks["q-f1.ball_future"] = {
    run = function()
        if (IsAtLeast(ActualIntellect, 60)) then
            evt.SimpleMessage(NPCText(45580, "The countless futures of the Dragon stream into your brain like fire licking at tender wood. You break its grip before you are destroyed, and can only mutter the words: The possibilities are unlimited."))
            return
        end
        evt.DamagePlayer(Players.Current, const.Damage.Mind, 70)
        SetValue(Weak, 1)
        evt.SimpleMessage(NPCText(45581, "The lock is instantaneous, and endless futures flash before you. The mortal shell you wear cannot hold what the mind now sees. Fire flares in your head, and the link breaks just in time."))
    end,
}

XeenQuests.hooks["q-f1.ball_mind"] = {
    run = function()
        if (IsAtLeast(ActualIntellect, 60)) then
            evt.SimpleMessage(NPCText(45576, "As your mind links with the Dragon's, its knowledge fills your brain with fire. You break the link before it is overloaded, weak and drained, and find yourself saying one phrase over and over: The knowledge is limitless."))
            return
        end
        evt.DamagePlayer(Players.Current, const.Damage.Mind, 70)
        SetValue(Weak, 1)
        evt.SimpleMessage(NPCText(45577, "As your mind links with the Dragon you feel its knowledge combine with your own. Your feeble mind tries to absorb the new wisdom but is found lacking. You tear yourself away, your head ringing."))
    end,
}

XeenQuests.hooks["q-f1.ball_past"] = {
    run = function()
        if (IsAtLeast(ActualIntellect, 60)) then
            evt.SimpleMessage(NPCText(45578, "The past of the Dragon fills your brain, faster and faster, towards the creation of time and beyond. You break the link in a desperate attempt at self preservation, and the words tumble from your lips: The history is endless."))
            return
        end
        evt.DamagePlayer(Players.Current, const.Damage.Mind, 70)
        SetValue(Weak, 1)
        evt.SimpleMessage(NPCText(45579, "Images of times long past fill your mind, and you watch worlds being uncreated. You try to break free from the grip of the Dragon and only just manage it. Your body aches as if something had been trying to leave it."))
    end,
}

