XeenQuests.hooks["x9.offering_1"] = {
    run = function()
        if not (IsQBitSet(QBit(110047))) then
            evt.DamagePlayer(Players.All, const.Damage.Air, 80)
            evt.SimpleMessage(NPCText(48206, "A gust of wind strikes you from the statue's hands. It is kept for Crusaders."))
            return
        end
        if (evt.GetMapVar("x9_offering_1", 0) == 1) then
            evt.SimpleMessage(NPCText(48207, "The statue's hands are empty."))
            return
        end
        evt.SetMapVar("x9_offering_1", 1)
        evt.GiveItem(5, 0)
        evt.SimpleMessage(NPCText(48208, "The statue's open hands hold a gift for a Crusader."))
    end,
}

