XeenQuests.hooks["xd07.book_languages"] = {
    run = function()
        if IsQBitSet(QBit(116240)) then
            evt.SimpleMessage(NPCText(47606, "The Book of Languages: a grammar of every tongue of Cloudside, from the dwarves' runes to the gremlins' squeaks. Someone has underlined 'Please' and 'Thank you' in all of them."))
            return
        end
        SetQBit(QBit(116240))
        evt.ForPlayer(Players.All)
        SetAward(Award(420))
        evt.SimpleMessage(NPCText(47607, "The Book of Languages: a grammar of every tongue of Cloudside, from the dwarves' runes to the gremlins' squeaks. Someone has underlined 'Please' and 'Thank you' in all of them. An afternoon with it, and the old runes on the cloud statues will make sense to you. (Linguist)"))
    end,
}

