XeenQuests.hooks["xd17.well"] = {
    run = function()
        if (IsPlayerBitSet(PlayerBit(11358))) then
            evt.StatusText(NPCText(47863, "The water is cool and refreshing."), 4)
            return
        end
        AddValue(Experience, 15000)
        SetAward(Award(421))
        SetPlayerBit(PlayerBit(11358))
        evt.StatusText(NPCText(47864, "Congratulations, You found Shangri-La! The water tastes of every road that led here. (+15,000 experience)"), 6)
    end,
}

